/**
 * The hosted playground (GitHub Pages, https://niyankhadka.github.io/yantra/):
 *   npm run dev:playground     http://localhost:3001/yantra/
 *   npm run build:playground   -> dist-pages/ (static files, no backend)
 * It reuses src/core and adds two generated files: viewer-shell.html (the
 * single-file viewer from lib/build.js appShell(), which the page fills with a
 * payload exactly as `yantra build` does) and sw.js (an offline cache of the site).
 * YANTRA_PLAYGROUND_BASE overrides the base path (default /yantra/).
 */
import crypto from 'node:crypto';
import path from 'node:path';
import { defineConfig } from 'vite';
import { appShell, resolveLevels, resolvePage, ROOT } from '../lib/build.js';

/** Gallery examples: page `src` and drill-down `$ref` files inlined at import time (as the root vite.config.js does). */
function inlineRefs() {
  return {
    name: 'yantra-playground-refs',
    enforce: 'pre',
    transform(code, id) {
      const file = id.split('?')[0];
      if (!file.endsWith('.json') || (!code.includes('"$ref"') && !/"kind"\s*:\s*"page"/.test(code))) return null;
      let payload;
      try {
        payload = JSON.parse(code);
      } catch {
        return null;
      }
      const dir = path.dirname(file);
      const out = payload?.kind === 'page' ? resolvePage(payload, dir) : resolveLevels(payload, dir, { root: ROOT });
      return { code: JSON.stringify(out), map: null };
    }
  };
}

/** viewer-shell.html (dev: served on request; build: emitted) and the offline service worker. */
function playgroundFiles() {
  let base = '/';
  return {
    name: 'yantra-playground-files',
    configResolved(config) {
      base = config.base;
    },
    configureServer(server) {
      server.middlewares.use((req, res, next) => {
        if (!req.url || !req.url.split('?')[0].endsWith('/viewer-shell.html')) return next();
        try {
          res.setHeader('Content-Type', 'text/html; charset=utf-8');
          res.end(appShell());
        } catch (err) {
          res.statusCode = 500;
          res.end(String(err?.message || err));
        }
      });
    },
    generateBundle(_, bundle) {
      this.emitFile({ type: 'asset', fileName: 'viewer-shell.html', source: appShell() });
      this.emitFile({ type: 'asset', fileName: '.nojekyll', source: '' });
      const files = [...new Set(['./', ...Object.keys(bundle).filter((f) => f !== 'index.html' && f !== '.nojekyll')])].sort();
      const version = crypto.createHash('sha256').update(files.join('\n')).digest('hex').slice(0, 12);
      this.emitFile({ type: 'asset', fileName: 'sw.js', source: serviceWorker(files, version) });
    }
  };
}

/** Cache-first service worker: precaches every file of this build, drops older caches. */
function serviceWorker(files, version) {
  return `// Generated by playground/vite.config.js: offline cache for the Yantra playground
const CACHE = 'yantra-playground-${version}';
const FILES = ${JSON.stringify(files)};
self.addEventListener('install', (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(FILES.map((f) => new URL(f, self.registration.scope)))).then(() => self.skipWaiting()));
});
self.addEventListener('activate', (e) => {
  e.waitUntil(caches.keys().then((keys) => Promise.all(keys.filter((k) => k.startsWith('yantra-playground-') && k !== CACHE).map((k) => caches.delete(k)))).then(() => self.clients.claim()));
});
self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== self.location.origin) return;
  // Pages: network first, so a new deploy shows at once; the cached copy when offline
  if (req.mode === 'navigate') {
    e.respondWith(fetch(req).catch(() => caches.match(new URL('./', self.registration.scope))));
    return;
  }
  e.respondWith(
    caches.match(req, { ignoreSearch: true }).then((hit) => {
      if (hit) return hit;
      return fetch(req).catch(() => (req.mode === 'navigate' ? caches.match(new URL('./', self.registration.scope)) : Response.error()));
    })
  );
});
`;
}

export default defineConfig({
  root: path.join(ROOT, 'playground'),
  base: process.env.YANTRA_PLAYGROUND_BASE || '/yantra/',
  publicDir: false,
  plugins: [inlineRefs(), playgroundFiles()],
  server: { port: 3001, fs: { allow: [ROOT] } },
  preview: { port: 4174 },
  build: {
    outDir: path.join(ROOT, 'dist-pages'),
    emptyOutDir: true,
    assetsInlineLimit: 0,
    // The core (validator, layout, every interface language) is one module graph by design
    chunkSizeWarningLimit: 1200
  }
});
